        engineeringData: { blockDesign: "06A Cast Iron closed deck with integrated internal water pump.", crankshaft: "Forged Steel.", pistonSpeed: "15.4 m/s @ 5800 RPM.", alternator: "90 Amp.", rotatingAssembly: { pistonConstruction: "Cast Aluminum.", wristPinDiameter: "19 mm", connectingRodLength: "144 mm", rodBoltSize: "M8.5", crankMainJournal: "54.0 mm", crankRodJournal: "47.8 mm", rodRatio: "1.75" }, cylinderHead: { combustionChamberVol: "44cc", intakePortFlow: "Small-Port 20V DOHC.", valveSizes: "Intake 26.9mm / Exhaust 29.9mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "DOHC.", lifterType: "Hydraulic.", specialFeature: "Electronic VVT on intake cam." }, oilAndCooling: { oilSquirters: "Yes.", oilPumpType: "Chain-driven.", thermostatOpening: "87°C.", oilCooler: "Water-to-Oil." }, fuelSystem: { systemType: "MPI.", maxPressure: "3.0 Bar.", injectors: "Bosch EV12 280cc." }, tuningLimits: { maxSafeTorqueStock: "350 Nm", maxSafePowerStock: "300 hp", maxSafeRPM: "7000 RPM", weakestLink: "K03 Turbo and 19mm rods." }, electrical: { coils: "COP.", ecu: "Bosch ME7.5" } },
        recommendedParts: { description: "Use oversized oil filters, maintain the VVT system meticulously, and delete PCV/SAI clutter if legally possible.", parts: [ { category: "Timing Belt Kit", brand: "Continental", note: "This kit comprehensively includes the heavy-duty timing belt and the essential hydraulic tensioner damper." }, { category: "VVT Cam Tensioner", brand: "BorgWarner / SWAG", note: "The electronic VVT tensioner is crucial for ME7.5 timing, so avoid cheap aftermarket alternatives to prevent engine failure." }, { category: "Water Pump", brand: "HEPU", note: "Upgrading to a water pump with a heavy-duty metal impeller is absolutely mandatory to prevent overheating." }, { category: "Oil Filter", brand: "Mann-Filter", note: "This oversized diesel filter adds crucial oil capacity and is your best defense against catastrophic oil sludge." }, { category: "Spark Plugs", brand: "NGK", note: "These platinum-tipped spark plugs offer excellent longevity for stock setups, though BKR7E is preferred for tuned cars." }, { category: "Ignition Coils", brand: "NGK / Bosch", note: "Individual coil-on-plug units fail frequently under high heat, so it is highly recommended to keep a spare in the trunk." }, { category: "Valve Cover Gasket", brand: "Victor Reinz", note: "Replacing this gasket is vital to prevent oil from pooling in the spark plug wells and shorting out the ignition coils." }, { category: "Secondary Air Pump", brand: "Pierburg", note: "This high-quality replacement pump restores the emissions system functionality when the factory unit inevitably seizes from water ingress." }, { category: "Diverter Valve", brand: "Kayser", note: "Upgrading to the OEM '710N' valve from the Audi TT ensures the diaphragm will not tear under higher boost pressures." }, { category: "Turbocharger", brand: "BorgWarner", note: "Always stick to a genuine BorgWarner K03 unit, as cheap rebuilt turbochargers will fail rapidly under normal load." } ] },
